with filtered_departments as (select *, case when location in ('London', 'Chiang Mai') then 'Group A' else 'Other' end location_group from departments where dept_name = 'Finance' and budget between 2195000 and 2916000), Agg as (select dept_name, max(budget) - min(budget) budget_range, min(budget) min_budget from filtered_departments group by dept_name) select * from Agg where min_budget > 2415000;
